                    + " -> " + r.get(0).getUsername()
                    + " (session " + System.identityHashCode(
                        em.unwrap(SessionImpl.class)) + ")";
        })));
    }
    for (Future<String> f : futures) System.out.println(f.get());
    pool.shutdown();
}

