@Bean
public JPAQueryFactory unsafe(EntityManagerFactory emf) {
    return new JPAQueryFactory(emf.createEntityManager());   // 진짜다
}

@Test
void 위험한_빈() throws Exception {
    ExecutorService pool = Executors.newFixedThreadPool(2);
    List<Future<String>> futures = new ArrayList<>();
    for (String name : List.of("m1", "m2")) {
        futures.add(pool.submit(() -> {
            try {
                return name + " -> " + unsafe.selectFrom(member)
                        .where(member.username.eq(name)).fetchOne()
                        .getUsername();
            } catch (Exception e) {
                return name + " -> " + e.getClass().getSimpleName();
            }
        }));
    }
    for (Future<String> f : futures) System.out.println(f.get());
    pool.shutdown();
}

